void set_converter_pins(uint8_t input_probe_channel_ADC1, 
    uint8_t output_probe_channel_ADC1, 
    uint8_t control_pin, 
    uint32_t MOS_SWITCHING_FREQ
){

    ledc_timer_config_t ledc_timer {
        .speed_mode = LEDC_HIGH_SPEED_MODE,
        .duty_resolution = LEDC_TIMER_12_BIT,
        .timer_num = LEDC_TIMER_0,
        .freq_hz = MOS_SWITCHING_FREQ,
        .clk_cfg = LEDC_AUTO_CLK
    };

    ESP_ERROR_CHECK(ledc_timer_config(&ledc_timer));

    ledc_channel_config_t ledc_channel = {
        .gpio_num = control_pin,
        .speed_mode = LEDC_HIGH_SPEED_MODE,
        .channel = LEDC_CHANNEL_0,
        .intr_type = LEDC_INTR_DISABLE,
        .timer_sel = LEDC_TIMER_0,
        .duty = 4095,
        .hpoint = 0
    };

    ledc_channel_config(&ledc_channel);

}

uint16_t converter_out_regulator(
    float out_desired,
    uint16_t* global_input_val
){
    
    uint16_t input_voltage = 0;
    uint16_t drive_signal_calculated = 4095;
    static uint16_t drive_signal = 4095;

    input_voltage = *global_input_val;

    drive_signal_calculated = min(max(4095 - out_desired*multiplier_lut [input_voltage], 0.0f), 4095.0f);

    if(drive_signal_calculated != drive_signal){
        drive_signal = drive_signal_calculated;
        ledc_set_duty(LEDC_HIGH_SPEED_MODE, LEDC_CHANNEL_0, drive_signal);
        ledc_update_duty(LEDC_HIGH_SPEED_MODE, LEDC_CHANNEL_0);
    }

    return drive_signal;
}

